"use client"

import * as React from "react"
import { defineBasicExtension, type BasicExtension } from "prosekit/basic"
import {
  Priority,
  createEditor,
  union,
  type Editor,
  type Union,
} from "prosekit/core"
import {
  defineMention,
  type MentionAttrs,
  type MentionExtension,
} from "prosekit/extensions/mention"
import { definePlaceholder } from "prosekit/extensions/placeholder"
import {
  ProseKit,
  useEditor,
  useEditorDerivedValue,
  useKeymap,
} from "prosekit/react"
import { HashIcon, SendHorizontalIcon } from "lucide-react"
import { cn } from "cn"

import { Avatar } from "@/components/standard/avatar"
import { Button } from "@/components/standard/button"
import {
  EDITOR_FRAME_CLASS,
  EditorContent,
  EditorShell,
  readProseKitValue,
  useIsClient,
  useProseKitChange,
  type ProseKitValue,
} from "@/components/standard/prosekit/editor-frame"
import {
  SuggestionMenu,
  suggestionTrigger,
  type SuggestionItem,
} from "@/components/standard/prosekit/suggestion-menu"

export type MentionUser = { id: string; name: string; avatar?: string }
export type MentionTag = { id: string; label: string }
export type { MentionAttrs }

export type MentionComposerValue = ProseKitValue & {
  /** Every @user and #tag in the message, in order. */
  mentions: MentionAttrs[]
}

type ComposerEditor = Editor<Union<[BasicExtension, MentionExtension]>>

type MentionComposerProps = {
  users?: MentionUser[]
  tags?: MentionTag[]
  placeholder?: string
  /** Called on Enter or the send button. Shift+Enter adds a line break. */
  onSubmit?: (value: MentionComposerValue) => void
  onChange?: (value: MentionComposerValue) => void
  /** Empty the composer after a submit. */
  clearOnSubmit?: boolean
  disabled?: boolean
  /** Before the text, e.g. an attach button. */
  leading?: React.ReactNode
  /** Beside the send button, e.g. an emoji picker. */
  trailing?: React.ReactNode
  className?: string
  "aria-label"?: string
}

const USER_TRIGGER = suggestionTrigger("@")
const TAG_TRIGGER = suggestionTrigger("#")
const EMPTY_DOC = { type: "doc", content: [{ type: "paragraph" }] }

function initials(name: string) {
  return name
    .split(/\s+/)
    .slice(0, 2)
    .map((part) => part.charAt(0).toUpperCase())
    .join("")
}

function readComposerValue(editor: ComposerEditor): MentionComposerValue {
  const mentions: MentionAttrs[] = []
  editor.state.doc.descendants((node) => {
    if (node.type.name === "mention") {
      mentions.push(node.attrs as MentionAttrs)
    }
  })
  const value = readProseKitValue(editor)
  // A picked mention leaves a trailing space behind it.
  return { ...value, text: value.text.trim(), mentions }
}

/** No text and no mentions; line breaks alone don't count. */
function readIsEmpty(editor: ComposerEditor) {
  let empty = true
  editor.state.doc.descendants((node) => {
    if (node.isText ? node.text?.trim() : node.type.name === "mention") {
      empty = false
    }
    return empty
  })
  return empty
}

function MentionMenus({
  users,
  tags,
  onOpenChange,
}: {
  users: MentionUser[]
  tags: MentionTag[]
  onOpenChange: (menu: "user" | "tag", open: boolean) => void
}) {
  const editor = useEditor<Union<[BasicExtension, MentionExtension]>>()

  const userItems = React.useMemo<SuggestionItem[]>(
    () =>
      users.map((user) => ({
        value: user.name,
        label: user.name,
        leading: (
          <Avatar
            size="xs"
            src={user.avatar}
            alt=""
            fallback={initials(user.name)}
          />
        ),
        onSelect: () => {
          editor.commands.insertMention({
            id: user.id,
            value: `@${user.name}`,
            kind: "user",
          })
          editor.commands.insertText({ text: " " })
        },
      })),
    [editor, users]
  )

  const tagItems = React.useMemo<SuggestionItem[]>(
    () =>
      tags.map((tag) => ({
        value: tag.label,
        label: tag.label,
        leading: <HashIcon />,
        onSelect: () => {
          editor.commands.insertMention({
            id: tag.id,
            value: `#${tag.label}`,
            kind: "tag",
          })
          editor.commands.insertText({ text: " " })
        },
      })),
    [editor, tags]
  )

  return (
    <>
      {users.length > 0 ? (
        <SuggestionMenu
          trigger={USER_TRIGGER}
          items={userItems}
          emptyLabel="No people found"
          onOpenChange={(open) => onOpenChange("user", open)}
        />
      ) : null}
      {tags.length > 0 ? (
        <SuggestionMenu
          trigger={TAG_TRIGGER}
          items={tagItems}
          emptyLabel="No tags found"
          onOpenChange={(open) => onOpenChange("tag", open)}
        />
      ) : null}
    </>
  )
}

function SendButton({
  disabled,
  onSubmit,
}: {
  disabled: boolean
  onSubmit: () => void
}) {
  const empty = useEditorDerivedValue(readIsEmpty)
  return (
    <Button
      iconOnly
      size="sm"
      aria-label="Send"
      disabled={disabled || empty}
      onClick={onSubmit}
    >
      <SendHorizontalIcon />
    </Button>
  )
}

/**
 * A chat-style message box: type @ to mention a person and # to add a tag,
 * Enter to send, Shift+Enter for a new line. Mentions come back as data in
 * `onSubmit`, so they can notify people or link tags.
 */
function MentionComposer(props: MentionComposerProps) {
  const isClient = useIsClient()
  if (!isClient) {
    return (
      <EditorShell
        slot="mention-composer"
        className={cn("p-1", props.className)}
        contentClassName="min-h-7 py-1"
      />
    )
  }
  return <MentionComposerClient {...props} />
}

function MentionComposerClient({
  users = [],
  tags = [],
  placeholder = "Write a message… @ to mention, # to tag",
  onSubmit,
  onChange,
  clearOnSubmit = true,
  disabled = false,
  leading,
  trailing,
  className,
  "aria-label": ariaLabel = "Message",
}: MentionComposerProps) {
  const openMenus = React.useRef(new Set<string>())

  const [editor] = React.useState<ComposerEditor>(() =>
    createEditor({
      extension: union(
        defineBasicExtension(),
        defineMention(),
        definePlaceholder({ placeholder, strategy: "doc" })
      ),
    })
  )

  const submit = React.useCallback(() => {
    // Enter picks a suggestion while a menu is open.
    if (disabled || openMenus.current.size > 0 || readIsEmpty(editor)) {
      return false
    }
    onSubmit?.(readComposerValue(editor))
    if (clearOnSubmit) {
      editor.setContent(EMPTY_DOC)
    }
    editor.focus()
    return true
  }, [clearOnSubmit, disabled, editor, onSubmit])

  // Above the base keymap, so Enter sends instead of splitting the paragraph.
  const keymap = React.useMemo(() => ({ Enter: submit }), [submit])
  useKeymap(keymap, { editor, priority: Priority.high })

  const handleChange = React.useCallback(
    () => onChange?.(readComposerValue(editor)),
    [editor, onChange]
  )
  useProseKitChange(editor, onChange ? handleChange : undefined)

  return (
    <ProseKit editor={editor}>
      <div
        data-slot="mention-composer"
        data-disabled={disabled}
        className={cn(
          EDITOR_FRAME_CLASS,
          "flex-row items-end gap-1 p-1",
          disabled && "pointer-events-none opacity-50",
          className
        )}
      >
        {leading ? (
          <div className="flex shrink-0 items-center">{leading}</div>
        ) : null}
        <EditorContent
          editor={editor}
          aria-label={ariaLabel}
          className="max-h-48 min-h-0 min-w-0 flex-1 overflow-y-auto px-2 py-1"
        />
        <div className="flex shrink-0 items-center gap-1">
          {trailing}
          <SendButton disabled={disabled} onSubmit={() => submit()} />
        </div>
        <MentionMenus
          users={users}
          tags={tags}
          onOpenChange={(menu, open) => {
            if (open) {
              openMenus.current.add(menu)
            } else {
              openMenus.current.delete(menu)
            }
          }}
        />
      </div>
    </ProseKit>
  )
}

export { MentionComposer }

"use client"

import "prosekit/basic/style.css"

import * as React from "react"
import type { Node as ProseMirrorNode } from "prosekit/pm/model"
import type { Editor, NodeJSON } from "prosekit/core"
import { defineReadonly } from "prosekit/extensions/readonly"
import { useDocChange, useExtension } from "prosekit/react"
import { cn } from "cn"

export type ProseKitValue = {
  json: NodeJSON
  html: string
  text: string
}

/** The same bordered field as LexicalEditor and Textarea. */
export const EDITOR_FRAME_CLASS =
  "relative flex w-full flex-col rounded-lg border border-input bg-transparent text-sm focus-within:ring-3 focus-within:ring-ring/50 dark:bg-input/30"

// Positioners only place their popup; the popup draws the surface.
export const POSITIONER_CLASS = "z-50 block h-min w-min overflow-visible"

export const POPUP_CLASS =
  "box-border flex origin-(--transform-origin) flex-col rounded-lg bg-popover p-1 text-sm text-popover-foreground shadow-md ring-1 ring-foreground/10 transition transition-discrete duration-100 data-[state=closed]:scale-95 data-[state=closed]:opacity-0 starting:scale-95 starting:opacity-0 motion-reduce:transition-none"

export const POPUP_ITEM_CLASS =
  "flex cursor-default items-center gap-2 rounded-sm px-2 py-1.5 text-sm whitespace-nowrap outline-hidden select-none data-highlighted:bg-muted data-[danger]:text-destructive [&_svg]:size-4 [&_svg]:shrink-0 [&_svg]:text-muted-foreground"

/** Mentions and hard breaks count as text; other atoms (images, rules) don't. */
function leafText(node: ProseMirrorNode) {
  if (node.type.name === "mention") {
    return String(node.attrs.value ?? "")
  }
  return node.type.name === "hardBreak" ? "\n" : ""
}

export function readProseKitValue(editor: Editor): ProseKitValue {
  const doc = editor.state.doc
  return {
    json: editor.getDocJSON(),
    html: editor.getDocHTML(),
    text: doc.textBetween(0, doc.content.size, "\n\n", leafText),
  }
}

/** Calls `onChange` with the document after every edit. */
export function useProseKitChange(
  editor: Editor,
  onChange: ((value: ProseKitValue) => void) | undefined
) {
  const onChangeRef = React.useRef(onChange)
  React.useEffect(() => {
    onChangeRef.current = onChange
  })

  const handleChange = React.useCallback(() => {
    onChangeRef.current?.(readProseKitValue(editor))
  }, [editor])

  useDocChange(handleChange, { editor })
}

/** Makes the document read-only while `editable` is false. */
export function useProseKitEditable(editor: Editor, editable: boolean) {
  const readonly = React.useMemo(
    () => (editable ? null : defineReadonly()),
    [editable]
  )
  useExtension(readonly, { editor })
}

const subscribeNever = () => () => {}

/** ProseKit parses HTML with the DOM, so editors are only created in the browser. */
export function useIsClient() {
  return React.useSyncExternalStore(
    subscribeNever,
    () => true,
    () => false
  )
}

/** What SSR renders in an editor's place: the same frame, toolbar row and height. */
export function EditorShell({
  slot,
  className,
  contentClassName,
  toolbar,
}: {
  slot: string
  className?: string
  contentClassName?: string
  toolbar?: boolean
}) {
  return (
    <div
      data-slot={slot}
      aria-busy="true"
      className={cn(EDITOR_FRAME_CLASS, className)}
    >
      {toolbar ? (
        <div className="h-10 rounded-t-lg border-b border-border bg-muted/30" />
      ) : null}
      <div className={cn("min-h-40 px-3 py-2", contentClassName)} />
    </div>
  )
}

/**
 * The element ProseKit mounts into. ProseMirror adds its own classes to it, so
 * keep `className` steady: a new value makes React overwrite them.
 */
export function EditorContent({
  editor,
  className,
  ...props
}: React.ComponentProps<"div"> & { editor: Editor }) {
  const mount = React.useCallback(
    (element: HTMLDivElement | null) => editor.mount(element),
    [editor]
  )

  return (
    <div
      ref={mount}
      data-slot="editor-content"
      className={cn(
        "typeset typeset-editor min-h-40 px-3 py-2 outline-none",
        className
      )}
      {...props}
    />
  )
}

"use client"

import * as React from "react"
import { canUseRegexLookbehind } from "prosekit/core"
import {
  AutocompleteEmpty,
  AutocompleteItem,
  AutocompletePopup,
  AutocompletePositioner,
  AutocompleteRoot,
} from "prosekit/react/autocomplete"
import { cn } from "cn"

import {
  POPUP_CLASS,
  POPUP_ITEM_CLASS,
  POSITIONER_CLASS,
} from "@/components/standard/prosekit/editor-frame"

export type SuggestionItem = {
  /** Matched against the typed query. Defaults to `label`. */
  value?: string
  label: React.ReactNode
  leading?: React.ReactNode
  /** Right-aligned hint, e.g. the Markdown shortcut for a block. */
  hint?: React.ReactNode
  onSelect: () => void
}

/**
 * Matches `trigger` plus the query after it at a word start: "/", "/head",
 * "@ana". A space straight after the trigger ("/ foo") closes the menu.
 */
export function suggestionTrigger(trigger: string) {
  const escaped = trigger.replace(/[.*+?^${}()|[\]\\/]/g, "\\$&")
  return new RegExp(
    (canUseRegexLookbehind() ? String.raw`(?<!\S)` : "") +
      escaped +
      String.raw`(\S.*)?$`,
    "u"
  )
}

export function SuggestionMenu({
  trigger,
  items,
  emptyLabel = "No results",
  className,
  onQueryChange,
  onOpenChange,
}: {
  trigger: RegExp
  items: SuggestionItem[]
  emptyLabel?: React.ReactNode
  className?: string
  onQueryChange?: (query: string) => void
  onOpenChange?: (open: boolean) => void
}) {
  return (
    <AutocompleteRoot
      regex={trigger}
      onQueryChange={(event) => onQueryChange?.(event.detail)}
      onOpenChange={(event) => onOpenChange?.(event.detail)}
    >
      <AutocompletePositioner className={POSITIONER_CLASS}>
        <AutocompletePopup
          className={cn(
            POPUP_CLASS,
            "max-h-80 min-w-56 overflow-y-auto overscroll-contain",
            className
          )}
        >
          <AutocompleteEmpty
            className={cn(POPUP_ITEM_CLASS, "text-muted-foreground")}
          >
            {emptyLabel}
          </AutocompleteEmpty>
          {items.map((item, index) => (
            <AutocompleteItem
              key={item.value ?? index}
              value={
                item.value ??
                (typeof item.label === "string" ? item.label : undefined)
              }
              onSelect={item.onSelect}
              className={cn(POPUP_ITEM_CLASS, "scroll-my-1")}
            >
              {item.leading}
              <span className="flex-1 truncate">{item.label}</span>
              {item.hint ? (
                <kbd className="font-mono text-xs text-muted-foreground">
                  {item.hint}
                </kbd>
              ) : null}
            </AutocompleteItem>
          ))}
        </AutocompletePopup>
      </AutocompletePositioner>
    </AutocompleteRoot>
  )
}
